import { useState } from 'react';
import './master-detail-dialog.css';

type Item = { id: string; name: string; summary: string; owner: string; updated: string };
export function MasterDetailDialog({ items, onClose }: { items: Item[]; onClose: () => void }) {
  const [selectedId, setSelectedId] = useState(items[0]?.id);
  const selected = items.find(item => item.id === selectedId);
  return <div className="dialog-backdrop"><section className="master-detail" role="dialog" aria-modal="true" aria-labelledby="detail-title" aria-describedby="detail-summary">
    <aside aria-label="Items"><h2>Items</h2><div role="listbox" aria-label="Choose an item">{items.map(item => <button key={item.id} role="option" aria-selected={item.id === selectedId} onClick={() => setSelectedId(item.id)}>{item.name}</button>)}</div></aside>
    <div className="detail">{selected ? <><header><h1 id="detail-title">{selected.name}</h1><p id="detail-summary">{selected.summary}</p></header><dl><dt>Owner</dt><dd>{selected.owner}</dd><dt>Last updated</dt><dd>{selected.updated}</dd></dl><footer><button onClick={onClose}>Cancel</button><button className="primary" onClick={onClose}>Select item</button></footer></> : <p>Select an item.</p>}</div>
  </section></div>;
}
